{
    Console.WriteLine("Eu sou " + Nome);
}

// com PARAMETRO: recebe um valor de fora
public void Perder(int dano)
{
    Vida = Vida - dano;
}

// com RETORNO: o tipo entra no lugar do void
public string Ficha()
{
    return Nome + " (" + Vida + ")";
}

